property.referenceImpl:
def sol(guesses):
    secret = 82
    out = []
    for g in guesses:
        if g == secret:
            out.append("correct"); break
        elif g < secret:
            out.append("too low")
        else:
            out.append("too high")
    return "".join(line + "\n" for line in out)

